// SetTracks sets the stack holding a timeline's tracks.
//
// The stack's parent is set to the timeline, as upstream's does.
//
// Passing NodeNone puts a fresh empty stack there rather than nothing,
// because that is what upstream's setter does: its own test_timeline.py sets
// tracks to None and then asserts that tl.tracks is still a Stack. A
// timeline with no tracks at all is not a thing a caller can reach through
// upstream's API, so it is not one they can reach through this one.
//
// Whatever stack was there is not destroyed. It stays in the document,
// parentless, so it can be put somewhere else; dropping it is a separate
// Remove call. That is the same bargain DetachChild makes, and leaving its
// parent pointing at the timeline instead would mean an object claiming a
// parent that has disowned it. A displaced stack that some other timeline
// has since taken as its own keeps that timeline as its parent, since this
// one is not the timeline disowning it.
//
// A nil tracks means none.
//
// C: otio_timeline_set_tracks
func (t Timeline) SetTracks(tracks *Node) error {
	at := t.at()
	cTracks := C.otio_node_none()
	if tracks != nil {
		handle, err := at.doc.adopt(*tracks)
		if err != nil {
			return err
		}
		cTracks = handle
	}
	var cError C.OtioBuffer
	if status := C.otio_timeline_set_tracks(at.ptr, at.h, cTracks, &cError); status != C.OTIO_STATUS_OK {
		return statusError(status, cError)
	}
	runtime.KeepAlive(at.doc)
	return nil
}

